<div class="mb-6"><p class="mb-2 text-xs font-bold uppercase tracking-[.16em] text-brand-600 dark:text-brand-400">SUIVI</p><h1 class="text-title-md font-bold text-gray-800 dark:text-white/90">Candidatures des étudiants</h1><p class="mt-2 text-theme-sm text-gray-500 dark:text-gray-400">Acceptez ou refusez les demandes envoyées par les étudiants. Les demandes « À examiner » apparaissent en premier.</p></div>
<section class="rounded-2xl border border-gray-200 bg-white p-5 dark:border-gray-800 dark:bg-white/[0.03]"><div class="overflow-x-auto"><table class="w-full min-w-[820px] text-left text-theme-sm"><thead><tr class="border-y border-gray-100 text-xs uppercase tracking-wider text-gray-400 dark:border-gray-800"><th class="py-3 pr-4">Étudiant</th><th class="py-3 pr-4">Offre</th><th class="py-3 pr-4">Date</th><th class="py-3 pr-4">Statut</th><th class="py-3">Action</th></tr></thead><tbody>
<?php if ($applications === []): ?><tr><td colspan="5" class="py-8 text-center text-gray-500">Aucune candidature pour le moment.</td></tr><?php endif; ?>
<?php foreach ($applications as $a):
    $badge = match ($a['status']) {
        'Acceptée' => 'bg-success-50 text-success-700',
        'Refusée' => 'bg-error-50 text-error-700',
        default => 'bg-warning-50 text-warning-700',
    }; ?>
<tr class="border-b border-gray-100 last:border-0 dark:border-gray-800"><td class="py-4 pr-4 font-semibold text-gray-800 dark:text-white/90"><?= e($a['student_name']) ?><small class="mt-1 block font-normal text-gray-400"><?= e($a['student_email']) ?><?= $a['student_study'] !== '' ? ' · ' . e($a['student_study']) : '' ?></small></td><td class="py-4 pr-4 text-gray-600 dark:text-gray-300"><?= e($a['offer_title']) ?><small class="mt-1 block text-gray-400"><?= e($a['company']) ?> · <?= e($a['offer_id']) ?></small></td><td class="py-4 pr-4 text-gray-600 dark:text-gray-300"><?= e($a['date']) ?></td><td class="py-4 pr-4"><span class="rounded-full px-2.5 py-1 text-xs font-semibold <?= $badge ?>"><?= e($a['status']) ?></span></td><td class="py-4"><div class="flex gap-2"><?php foreach ([['Acceptée', 'Accepter', 'bg-success-50 text-success-700'], ['Refusée', 'Refuser', 'bg-error-50 text-error-700']] as [$value, $label, $cls]): ?><form method="post" action="<?= e(route('admin/applications')) ?>"><?= csrf_input() ?><input type="hidden" name="application_id" value="<?= e($a['id']) ?>"><input type="hidden" name="status" value="<?= e($value) ?>"><button class="rounded-lg <?= $cls ?> px-3 py-2 text-xs font-semibold" type="submit"<?= $a['status'] === $value ? ' disabled style="opacity:.5"' : '' ?>><?= e($label) ?></button></form><?php endforeach; ?></div></td></tr>
<?php endforeach; ?>
</tbody></table></div></section>
<p class="mt-4 text-xs text-gray-500 dark:text-gray-400">Le nouveau statut est visible côté étudiant dans « Mes candidatures ».</p>
